package baseline

import (
	"bytes"
	"embed"
	"fmt"
	"io/fs"
	"path"
	"sort"
	"strings"
)

// The presets are generated by tools/cacconv (scripts/gen-presets.sh).
//
//go:embed presets/*.yaml
var presetFS embed.FS

// Presets returns every built-in baseline, sorted by name.
func Presets() ([]*Baseline, error) {
	names, err := fs.Glob(presetFS, "presets/*.yaml")
	if err != nil {
		return nil, err
	}
	var out []*Baseline
	for _, n := range names {
		b, err := presetFS.ReadFile(n)
		if err != nil {
			return nil, err
		}
		bl, err := Load(bytes.NewReader(b))
		if err != nil {
			return nil, fmt.Errorf("preset %s: %w", path.Base(n), err)
		}
		out = append(out, bl)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out, nil
}

// PresetFor returns the built-in baseline for an os-release ID and
// VERSION_ID. VERSION_ID is matched as given, then by its major version
// for releases that number minor versions (RHEL 9.6 uses the 9 preset).
func PresetFor(id, versionID string) (*Baseline, error) {
	ps, err := Presets()
	if err != nil {
		return nil, err
	}
	major, _, _ := strings.Cut(versionID, ".")
	for _, try := range []string{versionID, major} {
		for _, b := range ps {
			if b.For(id, try) {
				return b, nil
			}
		}
	}
	return nil, fmt.Errorf("no built-in baseline for %s %s", id, versionID)
}
